package ncasa.shoppinglist.application;
import java.time.Clock;import java.util.UUID;import ncasa.shoppinglist.application.port.out.*;import ncasa.shoppinglist.domain.*;
public final class ShoppingListLifecycleUseCase{private final ShoppingListRepository lists;private final ShoppingListHouseholdAccessPort access;private final Clock clock;public ShoppingListLifecycleUseCase(ShoppingListRepository l,ShoppingListHouseholdAccessPort a,Clock c){lists=l;access=a;clock=c;}public ShoppingList trash(Long actor,UUID household,UUID id,long version){access.getContext(household,actor);var l=GetShoppingListUseCase.load(lists,id,household);UpdateShoppingListUseCase.checkVersion(l,version);l.trash(clock.instant());return lists.save(l);}public ShoppingList restore(Long actor,UUID household,UUID id,long version){access.getContext(household,actor);var l=GetShoppingListUseCase.load(lists,id,household);UpdateShoppingListUseCase.checkVersion(l,version);String base=l.name(),candidate=base;int suffix=2;while(lists.existsActiveName(household,ShoppingListName.of(candidate).normalized(),l.id())){String ending="_"+suffix++;candidate=base.substring(0,Math.min(base.length(),80-ending.length()))+ending;}l.restore(candidate,clock.instant());return lists.save(l);}public void purge(Long actor,UUID household,UUID id,long version){access.getContext(household,actor);var l=GetShoppingListUseCase.load(lists,id,household);UpdateShoppingListUseCase.checkVersion(l,version);if(l.status()!=ShoppingListStatus.TRASHED)throw new ShoppingListConflictException("Only trashed lists can be permanently deleted");lists.delete(l);}}
